fn solve(n: i8) -> i8 {
    // If n is odd, no rectangle with integer sides can have this perimeter
    if n % 2 != 0 {
        return 0;
    }
    
    // n is even, so we can work with half-perimeter
    let half = n / 2;
    
    // Count unordered pairs (a, b) with a < b and a + b = half
    // This is equivalent to counting positive integers a such that:
    // 1. a < half - a (which means a < half/2)
    // 2. a > 0
    // So a ranges from 1 to floor((half - 1)/2)
    
    // The number of such a is floor((half - 1)/2)
    let count = (half - 1) / 2;
    
    // Now adjust for squares (where a = b)
    // A square occurs when a = half - a, i.e., a = half/2
    // This only happens when half is even (n divisible by 4)
    if n % 4 == 0 {
        // Subtract 1 to exclude the square case
        count - 1
    } else {
        // n ≡ 2 mod 4, half is odd, so no square case
        count
    }
}